import {armyInspectionReport} from './army-report.js?v=123';
import {createCatalogLoader} from './army-catalog.js?v=123';
import {decodeArmyCode} from './army-code.js?v=122';
import {ARMY_EXAMPLES} from './army-examples.js?v=122';
import {previewArmy,exampleCode,label} from './army-import.js?v=122';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function installArmyImport({canImport,apply}){
 const dialog=document.createElement('dialog');dialog.id='armyImport';dialog.setAttribute('aria-label','官方军表导入');document.body.append(dialog);
 let catalog,preview,request=0;const loadCatalog=createCatalogLoader();
 dialog.addEventListener('close',()=>{if(!dialog.open){request++;preview=null;}});
 document.getElementById('armyImportBtn').onclick=async()=>{
  if(!canImport())return;const ticket=++request;
  dialog.innerHTML='<button class="close" aria-label="关闭军表导入">×</button><h2>官方军表导入</h2><p role="status">读取玉京资料…</p>';dialog.querySelector('.close').onclick=()=>dialog.close();dialog.showModal();
  try{catalog=await loadCatalog(201);if(ticket!==request||!dialog.open)return;show();dialog.querySelector('#armyTeam').value=document.getElementById('armyImportBtn').dataset.team||'0';}catch(e){if(ticket!==request||!dialog.open)return;dialog.querySelector('p').textContent='无法载入资料：'+e.message;const retry=document.createElement('button');retry.textContent='重新载入资料';retry.onclick=()=>{dialog.close();document.getElementById('armyImportBtn').click();};dialog.append(retry);}
 };
 function show(){preview=null;dialog.innerHTML=`<button class="close" aria-label="关闭军表导入">×</button><div class="eyebrow">ARMY IMPORT / 精确配置</div><h2>把你的军表带上战场</h2><p>支持官方 Army 代码或分享链接，玉京本军（201）与 Military Orders（103），1–2 个战斗组。配置按三个官方 ID 精确匹配；不会用默认装备替代。</p><label>导入到<select id="armyTeam"><option value="0">▲ 红队</option><option value="1">◆ 蓝队</option></select></label><label>官方军表代码<textarea id="armyCode" rows="4" maxlength="16000" placeholder="粘贴 Army Code 或 infinityuniverse.com/army/list/…"></textarea></label><label>测试军表<select id="armyFixtures"><option value="">选择用户提供的测试军表</option>${ARMY_EXAMPLES.map((e,i)=>`<option value="${i}">${escape(e.name)}</option>`).join('')}</select></label><div class="buttonpair"><button id="armyExample">填入双战斗组示例</button><button id="armyParse" class="primary">解析并预览</button></div><p class="micro">官方资料 ${escape(catalog.version)} · ${catalog.accessed} · ${catalog.entries.length} 个配置。支持已关联的 Ancillary（局中放置）；其他多形态、Spec-Ops 和增援暂不支持。</p><div id="armyPreview" aria-live="polite"></div>`;
  dialog.querySelector('.close').onclick=()=>dialog.close();dialog.querySelector('#armyExample').onclick=()=>{dialog.querySelector('#armyCode').value=exampleCode(catalog);invalidate();};dialog.querySelector('#armyFixtures').onchange=e=>{if(e.target.value!=='')dialog.querySelector('#armyCode').value=ARMY_EXAMPLES[+e.target.value].code;invalidate();};dialog.querySelector('#armyCode').oninput=invalidate;dialog.querySelector('#armyTeam').onchange=invalidate;dialog.querySelector('#armyParse').onclick=parse;
 }
 function invalidate(){request++;preview=null;dialog.querySelector('#armyPreview').replaceChildren();}
 async function parse(){const out=dialog.querySelector('#armyPreview'),ticket=++request,team=dialog.querySelector('#armyTeam').value;preview=null;const current=()=>ticket===request&&dialog.open&&dialog.querySelector('#armyPreview')===out&&dialog.querySelector('#armyTeam').value===team;try{
  const code=dialog.querySelector('#armyCode').value,id=decodeArmyCode(code).factionId;if(![103,201].includes(id))throw Error('当前资料库支持玉京与 Military Orders；不会跨阵营替换');out.textContent='读取该阵营的官方配置…';const data=await loadCatalog(id);if(!current()||dialog.querySelector('#armyCode').value!==code)return;preview=previewArmy(code,data);const p=preview;
  out.innerHTML=`<p class="micro">本次匹配资料：${escape(data.faction||String(id))} · ${escape(data.version)} · ${escape(data.accessed)}</p><h3>${escape(p.decoded.name||'未命名军表')}</h3><p>${p.points} / ${p.decoded.pointsLimit} PT · ${p.swc} SWC · ${p.units.length} 个已匹配单位</p>${p.decoded.groups.map(g=>`<section class="armyGroup"><h3>战斗组 ${g.id} <small>${g.members.length} 个条目</small></h3>${p.units.filter(u=>u.combatGroup===g.id).map(u=>`<article><b>${escape(u.name)}${u.lieutenant?' · 尉官':''}</b><small>${u.armyRef.unitId} / ${u.armyRef.groupId} / ${u.armyRef.optionId} · ${u.points} PT</small><p>${u.loadout.map(k=>escape(u.armyWeapons[k]?.name||k)).join(' / ')}</p><details><summary>对应技能与装备</summary><p>${escape(u.officialAbilities.join(' / ')||'无额外技能')}</p>${u.unsupported.length?`<p class="warning">未自动实现（对应动作不提供）：${escape(u.unsupported.join('；'))}</p>`:''}</details></article>`).join('')}</section>`).join('')}${p.errors.length?`<div class="warning"><b>无法导入，当前对局未改变</b><ul>${p.errors.map(e=>`<li>${escape(e)}</li>`).join('')}</ul></div>`:''}${p.warnings.length?`<p class="warning">有 ${p.warnings.length} 项规则未完整实现。未实现的武器／模式不进入动作菜单；被动规则可能影响结果，此军表只能用于已支持部分的教学演练。</p><label class="armyAck"><input id="armyAck" type="checkbox">我已查看各单位的未实现项，按当前支持范围演练</label>`:''}<p>确认后替换所选一方军表，并重新开始先攻与部署流程；另一方已导入的军表会保留；双方均须导入后才可开始正式对局。会备份当前对局，可用“撤销”恢复。</p><button id="armyReport">下载军表核对报告（自用）</button><button id="armyApply" class="primary wide" ${p.errors.length||p.warnings.length?'disabled':''}>确认导入 · 返回开局流程</button>`;
  out.querySelector('#armyReport').onclick=()=>{if(!current()||preview!==p)return;const url=URL.createObjectURL(new Blob([armyInspectionReport(p,data)],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='infi-sim-army-inspection.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
  const button=out.querySelector('#armyApply');if(out.querySelector('#armyAck'))out.querySelector('#armyAck').onchange=e=>button.disabled=p.errors.length>0||!e.target.checked;
  button.onclick=()=>{if(!current()||preview!==p||p.errors.length||!canImport())return;try{apply(p,+dialog.querySelector('#armyTeam').value);dialog.close();}catch(e){const msg=document.createElement('p');msg.className='warning';msg.textContent=e.message;out.append(msg);}};
 }catch(e){if(!current())return;preview=null;out.textContent=e.message;}}
}
